const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '自由落体' },
      { kind: 'text', payload: '静止 v₀=0' },
      { kind: 'text', payload: 'v' },
      { kind: 'text', payload: 'g' },
      { kind: 'text', payload: 'v、g 方向均竖直向下' }
    ];
  },
  render: function (input, metrics) {
    var vp = (input && input.viewport) || { widthDu: 360, heightDu: 480 };
    var W = vp.widthDu, H = vp.heightDu;
    var cx = W * 0.30;
    var r = Math.min(W, H) * 0.055;
    var yStart = H * 0.18;
    var yFall = H * 0.58;
    var yGround = H * 0.90;

    // 竖直下落轨迹：用短线段拼成虚线
    var guide = [];
    var yTop = yStart + r * 1.5;
    var yEnd = yGround - H * 0.012;
    var step = H * 0.03;
    var y = yTop;
    while (y < yEnd) {
      var y2 = Math.min(y + step * 0.55, yEnd);
      var seg = visualSdk.polyline([[cx, y], [cx, y2]]);
      for (var i = 0; i < seg.length; i++) guide.push(seg[i]);
      y = y + step;
    }

    var ground = visualSdk.polyline([[W * 0.08, yGround], [W * 0.92, yGround]]);
    var ball1 = visualSdk.circle(cx, yStart, r);
    var ball2 = visualSdk.circle(cx, yFall, r);

    var vx = cx + W * 0.16;
    var gx = cx + W * 0.34;
    var ay1 = yFall - r * 2.4;
    var vLen = yFall + r * 4.2;
    var gLen = yFall + r * 3.2;
    var vArrow = visualSdk.arrow(vx, ay1, vx, vLen, {});
    var gArrow = visualSdk.arrow(gx, ay1, gx, gLen, {});

    return {
      schemaVersion: 1,
      sceneId: 'free-fall',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: [
        { id: 'ground', commands: ground },
        { id: 'guide', commands: guide },
        { id: 'ball1', commands: ball1 },
        { id: 'ball2', commands: ball2 },
        { id: 'vArrow', commands: vArrow },
        { id: 'gArrow', commands: gArrow }
      ],
      root: { type: 'group', children: [
        { type: 'path', pathId: 'ground', stroke: '#26354a', strokeWidth: 2 },
        { type: 'path', pathId: 'guide', stroke: '#8a97a8', strokeWidth: 1.5 },
        { type: 'path', pathId: 'ball1', stroke: '#26354a', strokeWidth: 2, fill: '#e2ecf7' },
        { type: 'path', pathId: 'ball2', stroke: '#26354a', strokeWidth: 2, fill: '#b9d3ea' },
        { type: 'path', pathId: 'vArrow', stroke: '#1f6feb', strokeWidth: 2.5 },
        { type: 'path', pathId: 'gArrow', stroke: '#c0392b', strokeWidth: 2.5 },
        { type: 'label', text: '自由落体', x: W * 0.5, y: H * 0.08, fontSize: Math.max(14, H * 0.045), textAnchor: 'middle', fill: '#1b2733' },
        { type: 'label', text: '静止 v₀=0', x: cx - r * 1.5, y: yStart + r * 0.4, fontSize: Math.max(11, H * 0.032), textAnchor: 'end', fill: '#1b2733' },
        { type: 'label', text: 'v', x: vx + 8, y: (ay1 + vLen) / 2, fontSize: Math.max(13, H * 0.042), textAnchor: 'start', fill: '#1f6feb' },
        { type: 'label', text: 'g', x: gx + 8, y: (ay1 + gLen) / 2, fontSize: Math.max(13, H * 0.042), textAnchor: 'start', fill: '#c0392b' },
        { type: 'label', text: 'v、g 方向均竖直向下', x: W * 0.5, y: H * 0.965, fontSize: Math.max(11, H * 0.03), textAnchor: 'middle', fill: '#44576b' }
      ] }
    };
  }
};
